#!/usr/bin/env bash
# End-to-end check that keys generated by torv3-vanity work in Tor.
#
# Generates a few keys, deletes everything except hs_ed25519_secret_key, lets
# Tor (offline) re-create hostname and hs_ed25519_public_key from the secret
# key alone, and checks they are identical to what torv3-vanity wrote.
#
#   scripts/tor-compat-test.sh [path/to/torv3-vanity]      (needs `tor` in PATH)
set -euo pipefail

bin=${1:-target/release/torv3-vanity}
work=$(mktemp -d)
trap 'kill "${tor_pid:-}" 2> /dev/null || true; rm -rf "$work"' EXIT

"$bin" ab c2 zz -n 2 -o "$work/keys" --gpu off --quiet > /dev/null
mkdir -p "$work/tor/data"
chmod 700 "$work/tor" "$work/tor/data"
torrc="$work/torrc"
{
  echo "DataDirectory $work/tor/data"
  echo "DisableNetwork 1"
  echo "SocksPort 0"
  echo "Log notice stdout"
} > "$torrc"

count=0
for dir in "$work"/keys/*/; do
  name=$(basename "$dir")
  mkdir "$work/tor/$name"
  chmod 700 "$work/tor/$name"
  cp "$dir/hs_ed25519_secret_key" "$work/tor/$name/"
  echo "HiddenServiceDir $work/tor/$name" >> "$torrc"
  echo "HiddenServicePort 80 127.0.0.1:9" >> "$torrc"
  count=$((count + 1))
done
if [ "$count" -ne 6 ]; then
  echo "expected 6 key folders, found $count" >&2
  exit 1
fi

tor -f "$torrc" > "$work/tor.log" 2>&1 &
tor_pid=$!
for _ in $(seq 60); do
  ready=0
  for dir in "$work"/keys/*/; do
    [ -s "$work/tor/$(basename "$dir")/hostname" ] && ready=$((ready + 1))
  done
  [ "$ready" -eq "$count" ] && break
  sleep 1
done
kill "$tor_pid" 2> /dev/null || true

failed=0
for dir in "$work"/keys/*/; do
  name=$(basename "$dir")
  if cmp -s "$dir/hostname" "$work/tor/$name/hostname" \
    && cmp -s "$dir/hs_ed25519_public_key" "$work/tor/$name/hs_ed25519_public_key"; then
    echo "ok   $(cat "$dir/hostname")"
  else
    echo "FAIL $name"
    failed=1
  fi
done
if [ "$failed" -ne 0 ]; then
  cat "$work/tor.log"
  exit 1
fi
echo "Tor derived identical addresses and public keys for all $count keys."
